from django.db import migrations, models


def price_to_discount(apps, schema_editor):
    MentorPackage = apps.get_model("packages", "MentorPackage")
    for package in MentorPackage.objects.select_related("service"):
        service = package.service
        extra = service.in_person_extra_cents if package.format == "in_person" else 0
        regular = (service.price_cents + extra) * package.session_count
        if regular > 0 and package.price_cents < regular:
            package.discount_percent = min(50, max(0, round(100 * (1 - package.price_cents / regular))))
            package.save(update_fields=["discount_percent"])


